macro_rules! FutureIncompatibilityReason {
    () => {
        # [doc = " The reason for future incompatibility"] # [doc = ""] # [doc = " Future-incompatible lints come in roughly two categories:"] # [doc = ""] # [doc = " 1. There was a mistake in the compiler (such as a soundness issue), and"] # [doc = "    we're trying to fix it, but it may be a breaking change."] # [doc = " 2. A change across an Edition boundary, typically used for the"] # [doc = "    introduction of new language features that can't otherwise be"] # [doc = "    introduced in a backwards-compatible way."] # [doc = ""] # [doc = " See <https://rustc-dev-guide.rust-lang.org/bug-fix-procedure.html> and"] # [doc = " <https://rustc-dev-guide.rust-lang.org/diagnostics.html#future-incompatible-lints>"] # [doc = " for more information."] # [derive (Copy , Clone , Debug)] pub enum FutureIncompatibilityReason { # [doc = " This will be an error in a future release for all editions"] # [doc = ""] # [doc = " Choose this variant when you are first introducing a \"future"] # [doc = " incompatible\" warning that is intended to eventually be fixed in the"] # [doc = " future."] # [doc = ""] # [doc = " After a lint has been in this state for a while and you feel like it is ready to graduate"] # [doc = " to warning everyone, consider setting [`FutureIncompatibleInfo::report_in_deps`] to true."] # [doc = " (see it's documentation for more guidance)"] # [doc = ""] # [doc = " After some period of time, lints with this variant can be turned into"] # [doc = " hard errors (and the lint removed). Preferably when there is some"] # [doc = " confidence that the number of impacted projects is very small (few"] # [doc = " should have a broken dependency in their dependency tree)."] FutureReleaseError , # [doc = " Code that changes meaning in some way in a"] # [doc = " future release."] # [doc = ""] # [doc = " Choose this variant when the semantics of existing code is changing,"] # [doc = " (as opposed to [`FutureIncompatibilityReason::FutureReleaseError`],"] # [doc = " which is for when code is going to be rejected in the future)."] FutureReleaseSemanticsChange , # [doc = " Previously accepted code that will become an"] # [doc = " error in the provided edition"] # [doc = ""] # [doc = " Choose this variant for code that you want to start rejecting across"] # [doc = " an edition boundary. This will automatically include the lint in the"] # [doc = " `rust-20xx-compatibility` lint group, which is used by `cargo fix"] # [doc = " --edition` to do migrations. The lint *should* be auto-fixable with"] # [doc = " [`Applicability::MachineApplicable`]."] # [doc = ""] # [doc = " The lint can either be `Allow` or `Warn` by default. If it is `Allow`,"] # [doc = " users usually won't see this warning unless they are doing an edition"] # [doc = " migration manually or there is a problem during the migration (cargo's"] # [doc = " automatic migrations will force the level to `Warn`). If it is `Warn`"] # [doc = " by default, users on all editions will see this warning (only do this"] # [doc = " if you think it is important for everyone to be aware of the change,"] # [doc = " and to encourage people to update their code on all editions)."] # [doc = ""] # [doc = " See also [`FutureIncompatibilityReason::EditionSemanticsChange`] if"] # [doc = " you have code that is changing semantics across the edition (as"] # [doc = " opposed to being rejected)."] EditionError (Edition) , # [doc = " Code that changes meaning in some way in"] # [doc = " the provided edition"] # [doc = ""] # [doc = " This is the same as [`FutureIncompatibilityReason::EditionError`],"] # [doc = " except for situations where the semantics change across an edition. It"] # [doc = " slightly changes the text of the diagnostic, but is otherwise the"] # [doc = " same."] EditionSemanticsChange (Edition) , # [doc = " This will be an error in the provided edition *and* in a future"] # [doc = " release."] # [doc = ""] # [doc = " This variant a combination of [`FutureReleaseError`] and [`EditionError`]."] # [doc = " This is useful in rare cases when we want to have \"preview\" of a breaking"] # [doc = " change in an edition, but do a breaking change later on all editions anyway."] # [doc = ""] # [doc = " [`EditionError`]: FutureIncompatibilityReason::EditionError"] # [doc = " [`FutureReleaseError`]: FutureIncompatibilityReason::FutureReleaseError"] EditionAndFutureReleaseError (Edition) , # [doc = " This will change meaning in the provided edition *and* in a future"] # [doc = " release."] # [doc = ""] # [doc = " This variant a combination of [`FutureReleaseSemanticsChange`]"] # [doc = " and [`EditionSemanticsChange`]. This is useful in rare cases when we"] # [doc = " want to have \"preview\" of a breaking change in an edition, but do a"] # [doc = " breaking change later on all editions anyway."] # [doc = ""] # [doc = " [`EditionSemanticsChange`]: FutureIncompatibilityReason::EditionSemanticsChange"] # [doc = " [`FutureReleaseSemanticsChange`]: FutureIncompatibilityReason::FutureReleaseSemanticsChange"] EditionAndFutureReleaseSemanticsChange (Edition) , # [doc = " A custom reason."] # [doc = ""] # [doc = " Choose this variant if the built-in text of the diagnostic of the"] # [doc = " other variants doesn't match your situation. This is behaviorally"] # [doc = " equivalent to"] # [doc = " [`FutureIncompatibilityReason::FutureReleaseError`]."] Custom (& 'static str) , }
    };
}

FutureIncompatibilityReason!();